#include <cstdio>

struct Tracer {
  const char* name;
  explicit Tracer(const char* n) : name(n) { std::printf("make %s\n", name); }
  ~Tracer() { std::printf("drop %s\n", name); }
};

Tracer global("global");

Tracer make(const char* n) { return Tracer(n); }

void f() {
  static Tracer once("static in f");
  Tracer local("local in f");
}

int main() {
  std::puts("main starts");
  Tracer a("a");
  f();
  f();
  Tracer* heap = new Tracer("heap");
  make("temporary");
  const Tracer& kept = make("kept by const&");
  std::printf("using %s\n", kept.name);
  delete heap;
  std::puts("main ends");
}

