#include <cstdio>

int next_id() {
  static int counter = 0;  // one object for the whole program
  return ++counter;
}

int main() {
  for (int i = 0; i < 3; ++i) {
    int square = i * i;    // a new object on every pass through the loop
    std::printf("id %d, square %d\n", next_id(), square);
  }
  int* p = new int(42);    // lives until delete
  std::printf("heap value %d\n", *p);
  delete p;
}

#include <cstdio>
#include <thread>

int& counter() {
  static int value = 0;  // made on the first call, lives until after main
  return value;
}

int count_call() {
  thread_local int calls = 0;  // a separate object in every thread
  return ++calls;
}

int main() {
  ++counter();
  ++counter();
  ++counter();
  std::printf("counter %d\n", counter());

  int seen[2] = {};
  std::thread a([&] { count_call(); seen[0] = count_call(); });
  std::thread b([&] { seen[1] = count_call(); });
  a.join();
  b.join();
  std::printf("thread a saw %d, thread b saw %d, main sees %d\n", seen[0], seen[1], count_call());
}

#include <cstdio>

struct Part {
  const char* name;
  explicit Part(const char* n) : name(n) { std::printf("  make %s\n", name); }
  ~Part() { std::printf("  drop %s\n", name); }
};

struct Base {
  Part engine{"Base::engine"};
  Base() { std::puts("  Base body"); }
  ~Base() { std::puts("  ~Base body"); }
};

struct Robot : Base {
  Part left;
  Part right;
  Robot() : left("Robot::left"), right("Robot::right") { std::puts("  Robot body"); }
  ~Robot() { std::puts("  ~Robot body"); }
};

int main() {
  std::puts("build:");
  {
    Robot r;
    std::puts("destroy:");
  }
}

