};

#include <cstdio>

struct Part {
  const char* name;
  explicit Part(const char* n) : name(n) { std::printf("make %s\n", name); }
  ~Part() { std::printf("drop %s\n", name); }
};

struct Lens {
  Part glass{"glass"};
};

struct Sensor {
  Part chip{"chip"};
  Part clock{"clock"};
};

struct Camera : Sensor {
  Lens lens;
};

Camera front;

void use_back() {
  static Camera back;
}

int main() {
  std::puts("main");
  use_back();
  use_back();
  std::puts("main ends");
}

#include <cstdio>
#include <string>

std::string make_name() { return "robot-7"; }

int main() {
  std::printf("%zu\n", make_name().size());
  const std::string& kept = make_name();
  std::string&& also_kept = make_name();
  std::printf("%s %s\n", kept.c_str(), also_kept.c_str());
}

#include <cstdio>
#include <string>

std::string make_name() { return "robot-7 with a name longer than fifteen"; }

struct View {
  const std::string& name;
  explicit View(const std::string& n) : name(n) {}
};

int main() {
  View v(make_name());  // the temporary is destroyed at the end of this line
  std::printf("%zu\n", v.name.size());
}

