#include <string>

std::string make_name() { return "robot-7"; }

struct View {
  const std::string& name;
  explicit View(const std::string& n) : name(n) {}
  View(std::string&&) = delete;  // a temporary picks this overload and fails
};

int main() {
  View v(make_name());
  return static_cast<int>(v.name.size());
}

#include <string>

const std::string& greeting() {
  std::string text = "hello";
  return text;  // text is destroyed here and the caller gets a dangling reference
}

int main() { return static_cast<int>(greeting().size()); }

#include <cstdio>
#include <vector>

struct Robot {
  std::vector<int> ids{1, 2, 3};
  const std::vector<int>& list() const { return ids; }
};

Robot make() { return {}; }

int main() {
  for (int id : make().list())  // C++20: the Robot is destroyed before the loop starts
    std::printf("%d\n", id);
}

